%% Generated by a Node 24 script from openmuse finance.ts and page-diff.ts
%% (do not edit by hand). Each expected value is the TS output; JSON values are
%% `JSON.stringify` text compared byte for byte with `muse_json:encode/1`.
-module(muse_engine_ref_tests).
-include_lib("eunit/include/eunit.hrl").

finance_test_() ->
    [{lists:flatten(io_lib:format("csv ~p", [I])), fun() -> check_finance(Csv, Exp) end}
     || {I, {Csv, Exp}} <- lists:enumerate(finance())].

check_finance(Csv, {ok, Json, Summary, Excerpt}) ->
    {ok, A} = muse_finance:analyze(Csv),
    ?assertEqual(Json, muse_json:encode(muse_finance:to_json(A))),
    ?assertEqual(Summary, muse_finance:summary(A)),
    ?assertEqual(Excerpt, muse_finance:excerpt(A));
check_finance(Csv, {error, Msg}) ->
    ?assertEqual({error, Msg}, muse_finance:analyze(Csv)).

to_fixed_test_() ->
    [?_assertEqual(Exp, muse_finance:to_fixed(F, D))
     || {Bits, D, Exp} <- to_fixed(), <<F/float>> <- [<<Bits:64>>]].

page_lines_test_() ->
    [?_assertEqual(Exp, muse_json:encode(muse_page_diff:page_lines(T, L)))
     || {T, L, Exp} <- page_lines()].

relative_times_test_() ->
    [?_assertEqual(Exp, muse_page_diff:without_relative_times(T)) || {T, Exp} <- relative()].

collapse_test_() ->
    [?_assertEqual(Exp, muse_page_diff:collapse_text(T)) || {T, Exp} <- collapse()].

diff_test_() ->
    [fun() ->
             D = muse_page_diff:diff_page(P, C),
             #{added := A, updated := U, removed := R} = D,
             ?assertEqual(Json, muse_json:encode({obj, [{added, A}, {updated, U}, {removed, R}]})),
             ?assertEqual(Describe, muse_page_diff:describe_page_diff(D)),
             ?assertEqual(Count, muse_page_diff:count_page_diff(D))
     end || {P, C, Json, Describe, Count} <- diffs()].

price_test_() ->
    [?_assertEqual({T, V, Exp}, {T, V, muse_page_diff:matches_price(T, V)})
     || {T, V, Exp} <- prices()].

contains_test_() ->
    [?_assertEqual({T, V, Exp}, {T, V, muse_page_diff:matches_contains(T, V)})
     || {T, V, Exp} <- contains()].

